public class Queue<T>
{
    private Node<T> First, Last;

    public Queue()
    {
        this.First = null;
        this.Last = null;
    }

    public bool IsEmpty()
    {
        return this.First == null;
    }

    public T Head()
    {
        return this.First.GetValue();
    }

    public void Insert(T x)
    {
        Node<T> Temp = new Node<T>(x);
        if (First == null)
        {
            First = Temp;
            Last = First;
        }
        else
        {
            Last.SetNext(Temp);
            Last = Last.GetNext();
        }
    }

    public T Remove()
    {
        T x = this.First.GetValue();
        this.First = this.First.GetNext();
        return x;
    }

    public override string ToString()
    {
        string str = "[";
        Node<T> Pos = First;
        while (Pos != null)
        {
            if (Pos.HasNext())
                str += Pos.GetValue() + ",";
            else
                str += Pos.GetValue();
            Pos = Pos.GetNext();
        }
        return str + "]";
    }
}

