{
    if (Q.IsEmpty()) return false;
    int L = Size(Q);// تعيد حجم Q
    if (L % 2 != 0) return false;
    Stack<int> S = new Stack<int>();
    for(int i=1; i<=L/2; i++)
        S.Push(Q.Remove());
    while (!S.IsEmpty() && !Q.IsEmpty())
        if (S.Pop() != Q.Remove())
            return false;
    if (S.IsEmpty() && Q.IsEmpty())
        return true;
    else
        return false;
}

